    "summaryLong": "캐나다 온타리오(Ontario) 지역이 탄소중립 에너지 체계 구축을 위해 소형모듈원자로(SMR)를 핵심 정책으로 채택했다. 온타리오는 지역 전력 공급 안정화와 산업용 열 공급, 수소 생산 등 다양한 용도로 소형모듈원자로의 활용을 추진하고 있다. 기존 원자력 발전소 부지와 새로운 입지의 활용을 통해 단계적으로 소형모듈원자로를 배치할 계획이다. 이러한 정책은 캐나다의 2050년 탄소중립 달성 목표와 지역 경제 활성화를 동시에 추구하는 전략이다.",
