    "summaryLong": "국제 핵에너지 전문기구인 경제협력개발기구 핵에너지기구(NEA)는 소형모듈원자로의 안전평가에 관한 국제 워크숍을 개최했다. 워크숍에서는 최근의 기술적 진전 사항과 규제 승인 과정에서의 과제들이 논의되었다. 각국의 규제 당국과 개발사들이 참여하여 안전 기준 조화와 평가 절차 개선방안을 모색했다. 이는 글로벌 소형모듈원자로 상용화 촉진을 위한 국제 협력의 중요한 사례로 평가된다.",
