    "summaryLong": "테네시주는 클린치 강 부지에 미국 최초의 상용 소형모듈원자로를 건설하기 위해 미국 에너지부(DOE)로부터 연방정부 지원금을 받게 되었다. 이는 테네시밸리청(TVA)이 주도하는 프로젝트로 미국의 원자력 에너지 정책 전환을 상징한다. 클린치 강 부지는 기존 원자력 시설과의 인접성으로 인해 인프라 활용이 용이하다. 성공적 완공 시 테네시주는 저탄소 에너지 기반 경제 발전의 거점이 될 것으로 기대된다.",
